using Intranet.Entity;
using Intranet.Service;
using Intranet.Api.Security;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.FileProviders;
using Microsoft.Extensions.Options;
using System.Security.Claims;
namespace Intranet.Api.Tests;
public sealed class AnalisisRbHistoryTests
{
 private static AnalisisRbSave Request()=>new(){RequestId=Guid.NewGuid(),Source=new(" j1825 ",217,1.404m,11.51m){ClientName="ROLLER RABBIT",FabricDescription="INTERLOCK"},UsedTime=11.51m,ServicePrice=1.30m,OtherExpenses=.03m};
 private static AnalisisRbHistoryService Service(Repo repo,bool write=true,bool permission=true,bool authenticated=true){var user=new ClaimsPrincipal(new ClaimsIdentity(authenticated?[new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")]:[],authenticated?"Test":null));return new(repo,new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer",EnableOrderRegistration=permission,AllowAllAuthenticatedWrites=permission}),new Env()),new RequestActor(user,write,false,false,true,"trace-test"));}
 [Fact]public void ComputesExcelValuesWithoutRoundingStoredResults(){var snapshot=AnalisisRbHistoryService.BuildSnapshot(Request(),new(2026,10,28));Assert.Equal("J1825",snapshot.Source.Np);Assert.Equal("ROLLER RABBIT",snapshot.Source.ClientName);Assert.Equal(1.404m,snapshot.Calculated.CommercialTotal);Assert.Equal(.104m,snapshot.Calculated.Difference);Assert.Equal(.104m/1.404m,snapshot.Calculated.Profitability);Assert.Equal(1.33m,snapshot.Calculated.ServiceWithExpenses);Assert.Equal(1.30m/11.51m,snapshot.Calculated.ServiceVm);Assert.Equal("COSTURA COMPLETA",snapshot.Calculated.Observation);Assert.Equal(new DateTime(2026,10,28),snapshot.AnalysisDate);}
 [Fact]public void PartialTimeUsesProportionalPrice(){var request=Request();request.UsedTime=5;var snapshot=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.Equal(5m*1.404m/11.51m,snapshot.Calculated.CommercialTotal);Assert.Equal(6.51m,snapshot.Calculated.RemovedTime);Assert.Equal("COSTURA PARCIAL",snapshot.Calculated.Observation);}
 [Fact]public void ZeroCommercialPricePreservesUndefinedPercentage(){var request=Request();request.Source=request.Source with{CommercialPrice=0};Assert.Null(AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today).Calculated.Profitability);}
 [Theory][InlineData(0,1,.03)][InlineData(-1,1,.03)][InlineData(11,-1,.03)][InlineData(11,1,-.03)]public void RejectsInvalidManualInputs(decimal time,decimal price,decimal expenses){var request=Request();request.UsedTime=time;request.ServicePrice=price;request.OtherExpenses=expenses;Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
 [Fact]public void RejectsMissingSourceOrIdAndExcessPrecision(){var request=Request();request.RequestId=Guid.Empty;Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));request=Request();request.Source=request.Source with{CommercialPrice=null};Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));request=Request();request.ServicePrice=.1234567m;Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
 [Fact]public async Task SaveUsesAuthenticatedActorAndPreservesRequestId(){var repo=new Repo();var request=Request();await Service(repo).Save(request,default);Assert.Equal(request.RequestId,repo.RequestId);Assert.Equal("OPERARIO",repo.User);Assert.Equal("trace-test",repo.Trace);Assert.Equal(217,repo.Snapshot!.Source.ProgrammedQuantity);}
 [Theory][InlineData(false,true,true)][InlineData(true,false,true)][InlineData(true,true,false)]public async Task SaveRejectsMissingWriteAuthorization(bool write,bool permission,bool authenticated){var repo=new Repo();await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>Service(repo,write,permission,authenticated).Save(Request(),default));Assert.Null(repo.Snapshot);}
 [Fact]public async Task HistoryNormalizesNpAndDoesNotRecomputeSnapshots(){var repo=new Repo();var result=await Service(repo,write:false).History(" j1825 ",12,1,default);Assert.Equal("J1825",repo.Np);Assert.Equal(12L,repo.Id);Assert.Equal("stored snapshot",Assert.Single(Assert.IsType<AnalisisRbHistoryPage>(result.Value).Rows).SnapshotJson);}
 [Theory][InlineData("J1825",0,1)][InlineData("J1825",1,0)][InlineData("J18%5",1,1)]public async Task InvalidHistoryRequestDoesNotReadDatabase(string np,long id,int page){var repo=new Repo();await Assert.ThrowsAsync<ArgumentException>(()=>Service(repo).History(np,id,page,default));Assert.Null(repo.Np);}
 [Fact]public void UsesQueryPermissionForHistoryAndSave(){Assert.Equal(new[]{"orders.query"},PortalAccessFilter.Required("AnalisisRbHistory","History","GET"));Assert.Equal(new[]{"orders.query"},PortalAccessFilter.Required("AnalisisRbHistory","Save","POST"));}
 [Fact]public void SnapshotPreservesImagePathAsViewed(){var request=Request();request.Source=request.Source with{ImagePath=@"\\hialpesa103\EstPro$\EP99863.jpg"};var snapshot=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.Equal(request.Source.ImagePath,snapshot.Source.ImagePath);var json=System.Text.Json.JsonSerializer.Serialize(snapshot);var restored=System.Text.Json.JsonSerializer.Deserialize<AnalisisRbSnapshot>(json);Assert.Equal(request.Source.ImagePath,restored!.Source.ImagePath);}
 [Fact]public void RejectsImagePathThatWouldBeTruncated(){var request=Request();request.Source=request.Source with{ImagePath=new string('X',1025)};Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
 private sealed class Repo:IAnalisisRbHistoryRepository{public AnalisisRbSnapshot? Snapshot;public Guid RequestId;public string? User,Trace,Np;public long? Id;public Task<AnalisisRbHistory> Insert(Guid id,AnalisisRbSnapshot snapshot,string user,string trace,CancellationToken ct){RequestId=id;Snapshot=snapshot;User=user;Trace=trace;return Task.FromResult(new AnalisisRbHistory{Id=12});}public Task<AnalisisRbHistoryPage> Read(string np,long? id,int page,CancellationToken ct){Np=np;Id=id;return Task.FromResult(new AnalisisRbHistoryPage([new(){Id=12,SnapshotJson="stored snapshot"}],1,1,1));}}
 private sealed class Env:IHostEnvironment{public string ApplicationName{get;set;}="Test";public string EnvironmentName{get;set;}="Production";public string ContentRootPath{get;set;}="";public IFileProvider ContentRootFileProvider{get;set;}=new NullFileProvider();}
}

